    }
  | {
      kind: "verdict";
      caseId: string;
      text: string;
      proposal?: { verdict: Verdict; reason?: string };
    }
  | { kind: "check-failed"; caseId: string; error: string };

export type PauseCause = "you" | "page" | "flag" | "between-cases" | "agent";

export type How = "checked" | "judged" | "marked" | "skipped" | "unchecked";

export type CaseRecord = {
  verdict: Verdict;
  how: How;
  note: string | null;
  yourNote: string | null;
  byHand: boolean;
  skippedSteps: string[];
  fixedSteps: string[];
  deniedSteps: string[];
  retries: number;
  // Steps that didn't work and the person did themselves, with what went
  // wrong. Records saved before these two fields existed lack them.
  handSteps?: Array<{ why: string; index: number; error: string }>;
  // The person used the page while a failure waited, then pressed Try again.
  touched?: boolean;
};

// The live panel's view of the whole kit: what it proves, every case with
// its steps and verdict, and a short feed of what just happened.
export type PlanCase = {
  id: string;
  title: string;
  proves: string | null;
  checks: string | null;
  // What a person judges at the end (expect.text), when the case has one.
