// Mouse and keyboard input made from inside the page. Real input (what
// Playwright sends over CDP) is trusted and has default actions; these events
// aren't, so each helper does by hand what the browser would have done next:
// focus on mousedown, the value change on a key, the hover chain on a move.
//
// Blueprint v3 reads event.which (0 on a constructed KeyboardEvent), which is
// why kits found that Blueprint "ignores synthetic key events"; keyEvent sets
// keyCode and which so Escape closes a dialog here too.

export type Point = { x: number; y: number };

const FOCUSABLE =
  'input, textarea, select, button, a[href], [tabindex], [contenteditable=""], [contenteditable="true"]';

export const center = (element: Element): Point => {
  const box = element.getBoundingClientRect();
  return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
};

const pointAt = (element: Element, position?: Point): Point => {
  if (!position) return center(element);
  const box = element.getBoundingClientRect();
  return { x: box.left + position.x, y: box.top + position.y };
};

const BUTTONS = { left: 0, middle: 1, right: 2 } as const;
const BUTTON_MASK = { left: 1, middle: 4, right: 2 } as const;

type MouseButton = keyof typeof BUTTONS;

// Playwright's selector syntax, as far as kits use it, for running inside the
// page: CSS with :has-text("…"), :text("…") and :visible, parts chained with
// >>, and >> nth=N. Text matches the way Playwright's do: case-insensitive,
// whitespace collapsed, a substring.
type Filter =
  | { kind: "has-text"; text: string }
  | { kind: "text"; text: string }
  | { kind: "visible" };
type Compound = { combinator: " " | ">" | "+" | "~"; css: string; filters: Filter[] };
type Part =
  | { kind: "css"; compounds: Compound[] }
  | { kind: "nth"; index: number }
  | { kind: "text"; text: string };
const normalize = (value: string): string =>
  value.replace(/\s+/g, " ").trim().toLowerCase();
const NO_TEXT = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "HEAD"]);
const NO_TEXT_SELECTOR = "script, style, noscript, template";
// Text the way Playwright reads it: script and style contents don't count.
const rawText = (node: Node): string => {
  if (node.nodeType === Node.TEXT_NODE) return node.nodeValue ?? "";
  if (node.nodeType !== Node.ELEMENT_NODE || NO_TEXT.has((node as Element).tagName)) return "";
  let text = "";
  for (const child of Array.from(node.childNodes)) text += rawText(child);
  return text;
};
export const elementText = (element: Element): string => {
  if (NO_TEXT.has(element.tagName)) return "";
  if (element instanceof HTMLInputElement && ["button", "submit", "reset"].includes(element.type)) {
    return normalize(element.value);
  }
  return normalize(element.querySelector(NO_TEXT_SELECTOR) ? rawText(element) : (element.textContent ?? ""));
};

