// Minimal CDP driver for a running Obsidian: evaluate, input, polling, screenshots, plugin reload.
import { resolveWebSocket } from "./websocket.mjs";

const POLL_MS = 25;
const json = JSON.stringify;

export const listTargets = async (port) => {
  const res = await fetch(`http://127.0.0.1:${port}/json/list`, {
    signal: AbortSignal.timeout(2000),
  });
  if (!res.ok) throw new Error(`CDP list failed: ${res.status}`);
  return (await res.json()).filter((t) => t.type === "page" && !t.url.startsWith("devtools://"));
};

const vaultMatchExpr = (root) =>
  `!!document.querySelector(".workspace") && typeof app !== "undefined" && ` +
  `app.vault?.adapter?.basePath === ${json(root)}`;

// Several page targets exist (one per vault, popouts, settings); match .workspace AND vault path.
export const findVaultTarget = async ({ port, root }) => {
  for (const target of await listTargets(port)) {
    const client = await open(target.webSocketDebuggerUrl);
    const ok = await client.evaluate(vaultMatchExpr(root)).catch(() => false);
    if (ok === true) return client;
    client.close();
  }
  return null;
};

export const connect = async ({ port, root, timeout = 30000 }) => {
  const deadline = Date.now() + timeout;
  for (;;) {
    const client = await findVaultTarget({ port, root }).catch(() => null);
    if (client) {
      await client.activate();
      return client;
    }
    if (Date.now() > deadline) throw new Error(`No CDP page target for vault ${root} on :${port}`);
    await new Promise((r) => setTimeout(r, 250));
  }
};

const open = async (url) => {
  const WebSocket = await resolveWebSocket();
  const ws = new WebSocket(url);
  let id = 0;
  const pending = new Map();

  await new Promise((resolve, reject) => {
    ws.addEventListener("open", resolve, { once: true });
    ws.addEventListener("error", (e) => reject(e.error ?? new Error("websocket error")), {
      once: true,
    });
  });
  ws.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data.toString());
